 "content": "def transform(grid):
    """Fill the single-cell gaps between same-colored markers in each row."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != row[0]]
        # The puzzle background is the most frequent value in the row; only
        # connect non-background cells when separated by background cells.
        from collections import Counter
        background = Counter(row).most_common(1)[0][0]
        markers = [c for c, value in enumerate(row) if value != background]
        for left, right in zip(markers, markers[1:]):
            if right - left > 1 and all(row[c] == background for c in range(left + 1, right)):
                for c in range(left + 1, right):
                    out[r][c] = 2
    return out
